interface Analytics {
  pageViews: number;
  uniqueVisitors: number;
  bounceRate: number;
}

interface Notification {
  id: number;
  message: string;
  read: boolean;
}

interface Settings {
  theme: string;
  language: string;
  notifications: boolean;
}

async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('/api/analytics').then(r => r.json()),
      fetch('/api/notifications').then(r => r.json()),
      fetch('/api/settings').then(r => r.json()),
    ]);

    return { analytics, notifications, settings };
  } catch {
    // Return mock data for build time
    return {
      analytics: { pageViews: 0, uniqueVisitors: 0, bounceRate: 0 } as Analytics,
      notifications: [] as Notification[],
      settings: { theme: 'light', language: 'en', notifications: true } as Settings,
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section>
        <h3>Analytics</h3>
        <p>Page Views: {analytics.pageViews}</p>
        <p>Unique Visitors: {analytics.uniqueVisitors}</p>
        <p>Bounce Rate: {analytics.bounceRate}%</p>
      </section>

      <section>
        <h3>Notifications</h3>
        {notifications.length === 0 ? (
          <p>No notifications</p>
        ) : (
          <ul>
            {notifications.map((n: Notification) => (
              <li key={n.id} style={{ fontWeight: n.read ? 'normal' : 'bold' }}>
                {n.message}
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h3>Settings</h3>
        <p>Theme: {settings.theme}</p>
        <p>Language: {settings.language}</p>
        <p>Notifications: {settings.notifications ? 'Enabled' : 'Disabled'}</p>
      </section>
    </div>
  );
}

